protocol BillingAPI {                        // local-looking delegate
    func createInvoice(_ cmd: CreateInvoice) async throws -> Invoice
}
actor BillingClient: BillingAPI {
    private let session: URLSession; private let base: URL
    init(session: URLSession, base: URL) { self.session = session; self.base = base }
    func createInvoice(_ cmd: CreateInvoice) async throws -> Invoice {
        var req = URLRequest(url: base.appending(path: "invoices"))
        req.httpMethod = "POST"; req.httpBody = try JSONEncoder().encode(cmd)
        do {
            let (data, response) = try await session.data(for: req)   // transport hidden
            guard let http = response as? HTTPURLResponse, (200..<300).contains(http.statusCode)
            else { throw BillingError.unavailable }
            return try JSONDecoder().decode(Invoice.self, from: data)
        } catch is CancellationError { throw CancellationError() }
          catch let error as URLError { throw BillingError.network(error) }
          catch let error as DecodingError { throw BillingError.decoding(error) }
    }
}
